import { useState } from 'react';
import { type Task, taskProgress } from './task-tree.js';
import { ProgressBar } from './progress-bar.js';
import { TaskForm } from './task-form.js';
import styles from './trellis-app.module.css';

/** Handlers for mutating the task tree. */
export type TaskActions = {
  onToggle: (id: string) => void;
  onAdd: (parentId: string, v: { title: string; description: string }) => void;
  onEdit: (id: string, v: { title: string; description: string }) => void;
  onRemove: (id: string) => void;
};

/**
 * A task row with its progress, rendered recursively for sub-tasks.
 * @param props.task - the task
 * @param props.depth - nesting level
 * @param props.color - project accent color
 */
export function TaskItem({ task, depth, color, actions }: { task: Task; depth: number; color?: string; actions: TaskActions }) {
  const [open, setOpen] = useState(true);
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(false);
  const hasChildren = task.subtasks?.length > 0;
  const p = taskProgress(task);

  return (
    <li className={styles.taskNode}>
      <div className={`${styles.taskRow} ${depth === 0 ? styles.taskRowTop : ''}`}>
        <button
          className={`${styles.caret} ${hasChildren ? '' : styles.caretHidden} ${open ? styles.caretOpen : ''}`}
          onClick={() => setOpen(!open)}
          aria-label={open ? 'Collapse' : 'Expand'}
        >
          ▸
        </button>
        <label className={styles.check}>
          <input type="checkbox" checked={task.done} onChange={() => actions.onToggle(task.id)} />
          <span className={styles.checkBox} style={task.done ? { background: color, borderColor: color } : undefined}>
            {task.done ? '✓' : ''}
          </span>
        </label>

        {editing ? (
          <div className={styles.taskMain}>
            <TaskForm
              initial={task}
              submitLabel="Save"
              onCancel={() => setEditing(false)}
              onSubmit={(v) => { actions.onEdit(task.id, v); setEditing(false); }}
            />
          </div>
        ) : (
          <div className={styles.taskMain} onDoubleClick={() => setEditing(true)}>
            <div className={styles.taskHead}>
              <span className={`${styles.taskTitle} ${task.done ? styles.taskDone : ''}`}>{task.title}</span>
              {hasChildren ? (
                <span className={styles.taskMeta}>
                  {p.done}/{p.total} · <strong>{p.percent}%</strong>
                </span>
              ) : null}
            </div>
            {task.description ? <p className={styles.taskDesc}>{task.description}</p> : null}
            {hasChildren ? <ProgressBar percent={p.percent} color={color} /> : null}
          </div>
        )}

        {!editing ? (
          <div className={styles.taskTools}>
            <button className={styles.iconBtn} title="Add sub-task" onClick={() => { setAdding(true); setOpen(true); }}>＋</button>
            <button className={styles.iconBtn} title="Edit" onClick={() => setEditing(true)}>✎</button>
            <button className={styles.iconBtn} title="Delete" onClick={() => actions.onRemove(task.id)}>🗑</button>
          </div>
        ) : null}
      </div>

      {open && (hasChildren || adding) ? (
        <ul className={styles.subList}>
          {task.subtasks.map((s) => (
            <TaskItem key={s.id} task={s} depth={depth + 1} color={color} actions={actions} />
          ))}
          {adding ? (
            <li className={styles.subForm}>
              <TaskForm
                placeholder={`New sub-task of "${task.title}"`}
                onCancel={() => setAdding(false)}
                onSubmit={(v) => actions.onAdd(task.id, v)}
              />
            </li>
          ) : null}
        </ul>
      ) : null}
    </li>
  );
}
